// ===== extracted inline script 15; id=needsHelpAutoInit =====
(function(){
  var btn  = document.getElementById("needsHelpBtn");
  var qbtn = document.getElementById("needsHelpNeedsBtn");
  var dlg  = document.getElementById("needsHelpNeeds");
  function openDlg(){ if (!dlg) return; if (typeof dlg.showModal==="function") dlg.showModal(); else dlg.setAttribute("open",""); }
  function closeDlg(){ if (!dlg) return; if (typeof dlg.close==="function") dlg.close(); else dlg.removeAttribute("open"); }
  if (btn)  btn.addEventListener("click", openDlg);
  if (qbtn) qbtn.addEventListener("click", openDlg);
  if (dlg){
    dlg.addEventListener("click", function(e){
      var r = dlg.getBoundingClientRect();
      var inside = e.clientX>=r.left && e.clientX<=r.right && e.clientY>=r.top && e.clientY<=r.bottom;
      if(!inside) closeDlg();
    });
    document.addEventListener("keydown", function(e){ if(e.key==="Escape" && dlg.open) closeDlg(); });
    var closeBtn = dlg.querySelector("[data-close-dialog]"); if (closeBtn) closeBtn.addEventListener("click", closeDlg);
  }
})();

