// ===== extracted inline script 16; id=none =====
// Close any open <dialog> when clicking outside its bounds
(function(){
  function isInside(rect, x, y){
    return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
  }
  function closeDlg(dlg){
    if (!dlg) return;
    if (typeof dlg.close === 'function') dlg.close(); else dlg.removeAttribute('open');
  }
  document.addEventListener('click', function(e){
    // Ignore middle/right clicks
    if (e.button && e.button !== 0) return;
    var openDlgs = document.querySelectorAll('dialog[open]');
    if (!openDlgs.length) return;
    openDlgs.forEach(function(dlg){
      var rect = dlg.getBoundingClientRect();
      if (!isInside(rect, e.clientX, e.clientY)) closeDlg(dlg);
    });
  }, true); // capture: сработает до других обработчиков
})();

