// ===== extracted inline script 17; id=none =====
(function(){
  if (window.__HEI_MANUAL_ADAPTER__) return;
  window.__HEI_MANUAL_ADAPTER__ = true;

  function ready(fn){ if (document.readyState!=='loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  if (typeof window.debounce !== 'function') {
    window.debounce = function(fn, ms){ var t,w=(+ms>0?+ms:160); return function(){ var a=arguments,c=this; clearTimeout(t); t=setTimeout(function(){ fn.apply(c,a); }, w); }; };
  }
  function $(id){ return document.getElementById(id); }
  function parseK(s){
    if (s==null) return NaN;
    var v=String(s).replace(/[\s_\u00A0\u202F]/g,'').replace(',', '.');
    var parts=v.split('.'); if(parts.length>2){ var d=parts.pop(); v=parts.join('')+'.'+d; }
    var n=Number(v); return Number.isFinite(n)?n:NaN;
  }
  function inRange(n){ return Number.isFinite(n) && n>=800 && n<=5000; }
  function clampK(n){ n=Math.round(n||0); if(n<800)n=800; if(n>5000)n=5000; return n; }

  function wire(){
    var manualRadio = $('heiManualRadio');
    var manualInput = $('heiManualKcal');
    var rbActual    = $('heiEnergyActual');
    var targetInput = $('heiTargetKcal');   // скрыт, но синхронизируем на всякий случай

    if (!manualRadio || !manualInput || !rbActual) return false;

    // скрыть "целевые ккал" радио (если остались рядом лейблы)
    try{
      var rbTarget = $('heiEnergyTarget');
      if (rbTarget && rbTarget.closest) { var lbl = rbTarget.closest('label'); if (lbl) lbl.style.display='none'; }
    }catch(_){}

    var lastValid = (window.Needs && inRange(window.Needs.targetKcal)) ? Math.round(window.Needs.targetKcal) : 2000;

    function recomputeSafe(){
      try { if (window.__heiInst && typeof window.__heiInst.recompute==='function') window.__heiInst.recompute(); } catch(_){}
      window.dispatchEvent(new Event('needs:changed'));
    }
    function setBadgeMode(){
      var badge = $('heiBadge');
      if (!badge) return;
      badge.textContent = manualRadio.checked ? 'нормировка: целевые (ручной ввод)' : 'нормировка: ккал рациона';
    }
    function syncEnabled(){
      manualInput.disabled = !manualRadio.checked;
      setBadgeMode();
    }
    function accept(v){
      lastValid = v;
      (window.Needs||(window.Needs={})).targetKcal = v;
      if (targetInput) targetInput.value = v;
    }

    // реакция режимов
    rbActual.addEventListener('change', function(){
      syncEnabled();
      recomputeSafe();
    });
    manualRadio.addEventListener('change', function(){
      if (manualRadio.checked && !manualInput.value) {
        manualInput.value = lastValid;
      }
      syncEnabled();
      if (manualRadio.checked && inRange(parseK(manualInput.value))) {
        accept(clampK(parseK(manualInput.value)));
        recomputeSafe();
      } else if (!manualRadio.checked) {
        recomputeSafe();
      }
    });

    // Ввод: НЕ трогаем поле, пока пользователь печатает; пересчитываем только при валидных 800–5000
    manualInput.addEventListener('input', debounce(function(){
      if (!manualRadio.checked) return;
      var v = parseK(manualInput.value);
      if (inRange(v)) { accept(Math.round(v)); recomputeSafe(); }
      // иначе ничего не делаем — позволяем допечатать
    }, 180));

    // Enter = принять
    manualInput.addEventListener('keydown', function(e){
      if (e.key === 'Enter') { e.preventDefault(); manualInput.blur(); }
    });

    // На блюре — добиваем до валидного числа и записываем
    manualInput.addEventListener('blur', function(){
      if (!manualRadio.checked) return;
      var v = parseK(manualInput.value);
      if (!inRange(v)) v = lastValid;
      v = clampK(v);
      manualInput.value = v;
      accept(v);
      recomputeSafe();
    });

    // начальная инициализация
    syncEnabled();
    return true;
  }

  ready(function(){
    if (wire()) return;
    var tries=0, t=setInterval(function(){ tries++; if (wire()||tries>40) clearInterval(t); }, 200);
  });
})();

;

