// __NEEDS_SEX_METHOD_ADAPTER__
(function(){ 
  if (window.__NEEDS_SEX_METHOD_ADAPTER__) return; window.__NEEDS_SEX_METHOD_ADAPTER__ = true;

  function normSex(val){
    var s = String(val||'').trim().toLowerCase();
    if (s === 'male' || /^m(ale)?$/.test(s) || /муж/.test(s)) return 'male';
    if (s === 'female' || /^f(emale)?$/.test(s) || /жен/.test(s)) return 'female';
    return 'female';
  }

  function ready(fn){ 
    if (document.readyState !== 'loading') fn(); 
    else document.addEventListener('DOMContentLoaded', fn); 
  }

  ready(function(){ 
    var sel = document.getElementById('needs_sex');
    if (sel) {
      Array.prototype.forEach.call(sel.options||[], function(op){
        var txt = (op.textContent||op.innerText||'').toLowerCase();
        if (/муж/.test(txt) || /^m(ale)?$/.test(txt)) op.value = 'male';
        if (/жен/.test(txt) || /^f(emale)?$/.test(txt)) op.value = 'female';
      });
      sel.value = normSex(sel.value);
      sel.addEventListener('change', function(){
        sel.value = normSex(sel.value);
        try { 
          if (window.recomputeNeeds) window.recomputeNeeds(); 
          else if (window.calcNeeds) window.calcNeeds(); 
        } catch(_){}
      });
    }

    var _orig = window.calcNeeds_internal;
    if (typeof _orig === 'function') {
      window.calcNeeds_internal = function(){ 
        try {
          var node = document.getElementById('needs_sex');
          if (node) node.value = normSex(node.value);
        } catch(_){}
        return _orig.apply(this, arguments);
      };
    }
  });
})();

