// ===== extracted inline script 19; id=none =====
(function(){
  function getCurrentRation(){
    if (window.Ration && Array.isArray(window.Ration.current)) {
      return window.Ration.current.map(function(it){
        return { key: it.key || it.id || it.name, grams: Number(it.grams||it.weight||0) || 0 };
      });
    }
    if (window.STATE && Array.isArray(window.STATE.ration)) {
      return window.STATE.ration.map(function(it){
        return { key: it.key || it.id || it.name, grams: Number(it.grams||it.weight||0) || 0 };
      });
    }
    var rows = Array.prototype.slice.call(document.querySelectorAll('#rationBody tr'));
    return rows.map(function(tr){
      var name = tr.querySelector('td:first-child') ? tr.querySelector('td:first-child').textContent.trim() : '';
      var gInput = tr.querySelector('input');
      var grams = gInput ? Number(gInput.value)||0 : 0;
      var key = tr.getAttribute('data-key') || name;
      return { key: key, name_fallback: name, grams: grams };
    });
  }
  function getPersonName(){
    var el = document.getElementById('needs_person_name');
    return el && el.value ? el.value.trim() : '';
  }
  function nowStr(){
    return (new Date()).toLocaleString();
  }
  function resolveName(key, fallback){
    try {
      if (window.DB && window.DB.byKey && window.DB.byKey.has(key)) {
        var p = window.DB.byKey.get(key);
        return p.name_ru || p.name || fallback || key;
      }
    } catch(e){}
    return fallback || key;
  }
  function downloadBlob(content, filename, type){
    var blob = new Blob([content], {type:type});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function(){ URL.revokeObjectURL(url); }, 1200);
  }
  function fileNameBase(){
    var d = new Date();
    function p(n){ return String(n).padStart(2,'0'); }
    return "ration_"+d.getFullYear()+"-"+p(d.getMonth()+1)+"-"+p(d.getDate())+"_"+p(d.getHours())+p(d.getMinutes());
  }
  function onExportJSON(){
    var arr = getCurrentRation();
    var name = getPersonName();
    var payload = {
      type: "ration_preset",
      version: 1,
      created_at: (new Date()).toISOString(),
      items: arr.map(function(it){ return { key: it.key, grams: it.grams }; })
    };
    if (name) payload.person_name = name;
    downloadBlob(JSON.stringify(payload, null, 2), fileNameBase()+".json", "application/json");
  }
  function onPrintRation(){
    var arr = getCurrentRation();
    var name = getPersonName();
    var dt = nowStr();
    var rows = arr.map(function(it, idx){
      var nm = resolveName(it.key, it.name_fallback);
      return '<tr><td>'+(idx+1)+'</td><td>'+nm+'</td><td style="text-align:right">'+(it.grams||0)+'</td></tr>';
    }).join('');
    var headHtml = document.head ? document.head.innerHTML : '';
    var html = '<!doctype html><html><head>'+headHtml+
      '<meta charset="utf-8"><title>Итоговый рацион</title>' +
      '<style>@media print{@page{size:A4;margin:14mm;}}' +
      'body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;}' +
      'h1{margin-top:0;}' +
      'table{width:100%;border-collapse:collapse;}' +
      'th,td{border:1px solid #ccc;padding:6px 8px;font-size:12px;}' +
      'th{background:#f4f7ff;}</style></head><body style="margin:0;padding:12px 16px;">';
    html += '<h1>Итоговый рацион</h1>';
    if (name) html += '<div style="font-weight:600;margin-bottom:4px;">Пациент: '+name+'</div>';
    html += '<div style="font-size:12px;margin-bottom:12px;">Дата и время: '+dt+'</div>';
    html += '<table><thead><tr><th style="width:36px;">#</th><th>Продукт</th><th style="width:110px;">Граммы</th></tr></thead><tbody>'+rows+'</tbody></table>';
  html += '</body></html>';
    var w = window.open('', '_blank');
    if (!w) { alert('Разрешите всплывающие окна для печати'); return; }
    w.document.open();
    w.document.write(html);
    w.document.close();
    try { w.focus(); w.print(); } catch(e){}
  }
  function onExportPDF(){
    // пока используем такой же вывод, пользователь в диалоге выберет "сохранить в PDF"
    onPrintRation();
  }
  function init(){
    var btnJ = document.getElementById('exportRationJsonBtn');
    var btnP = document.getElementById('exportRationPdfBtn');
    var btnPr= document.getElementById('printRationBtn');
    if (btnJ) btnJ.addEventListener('click', onExportJSON);
    if (btnP) btnP.addEventListener('click', onExportPDF);
    if (btnPr)btnPr.addEventListener('click', onPrintRation);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

