// ===== extracted inline script 20; id=none =====
(function(){
    function applyRationPresetObject(payload){
      var items = null;
      if (Array.isArray(payload)) items = payload;
      else if (payload && Array.isArray(payload.items)) items = payload.items;
      else if (payload && Array.isArray(payload.ration)) items = payload.ration;
      else if (payload && payload.data && Array.isArray(payload.data.items)) items = payload.data.items;
      if (!items) {
        alert('Файл не похож на сохранённый рацион. Ожидается массив продуктов или объект с полем items.');
        return;
      }
      var state = window.State;
      if (!state || typeof state.add !== 'function') {
        alert('Рацион ещё не готов к загрузке. Дождитесь завершения запуска калькулятора и повторите попытку.');
        return;
      }
      var valid = [];
      var skipped = [];
      items.forEach(function(it, index){
        if (!it || typeof it !== 'object') { skipped.push({index:index, reason:'invalid_entry'}); return; }
        var key = String(it.key || it.id || '');
        var grams = Math.max(0, Math.min(5000, Number(it.grams) || 0));
        if (!key || !(grams > 0)) { skipped.push({index:index, key:key, reason:'invalid_key_or_grams'}); return; }
        valid.push({ key:key, id:it.id || key, grams:grams, ai_import:it.ai_import || null });
      });
      if (!valid.length) {
        alert('В файле не найдено ни одной позиции с корректным ключом продукта и массой. Текущий рацион сохранён без изменений.');
        return;
      }
      var result = null;
      if (typeof state.replaceAll === 'function') {
        result = state.replaceAll(valid, 'json_import_v5_3_207');
      } else {
        var previous = typeof state.get === 'function' ? state.get() : [];
        try {
          if (typeof state.beginAddBatch === 'function') state.beginAddBatch('json_import_v5_3_207');
          state.clear();
          var imported = 0;
          valid.forEach(function(it){ if (state.add(it.key, it.grams, it.ai_import)) imported += 1; });
          if (typeof state.endAddBatch === 'function') state.endAddBatch('replaceAll', {source:'json_import_v5_3_207'});
          if (!imported && previous.length) {
            state.clear();
            previous.forEach(function(it){ state.add(it.key, it.grams, it.ai_import || null); });
            result = {ok:false, imported:0, skipped:valid.length, preserved_previous:true};
          } else result = {ok:imported>0, imported:imported, skipped:valid.length-imported, preserved_previous:false};
        } catch (e) {
          result = {ok:false, imported:0, skipped:valid.length, preserved_previous:true, error:String(e && e.message || e)};
        }
      }
      if (!result || !result.ok) {
        alert('Не удалось применить продукты из файла. Текущий рацион сохранён без изменений. Обновите страницу и повторите загрузку.');
        return;
      }
      var skippedCount = skipped.length + (Array.isArray(result.skipped) ? result.skipped.length : Number(result.skipped) || 0);
      try { window.dispatchEvent(new CustomEvent('ration:json-imported', {detail:{imported:Number(result.imported)||0, skipped:skippedCount}})); } catch(_) {}
      alert('Рацион загружен: ' + (Number(result.imported)||0) + ' поз.' + (skippedCount ? ' Пропущено: ' + skippedCount + '.' : ''));
    }

  function handlePresetFile(file){
    var reader = new FileReader();
    reader.onload = function(){
      try {
        var data = JSON.parse(String(reader.result||'{}'));
        if (Array.isArray(data)) {
          data = { type:"ration_preset", version:1, items: data };
        }
        applyRationPresetObject(data);
      } catch(e){
        console.error(e);
        alert('Ошибка чтения JSON: ' + e.message);
      }
    };
    reader.readAsText(file, 'utf-8');
  }

  function initPresetJsonLoader(){
    var btn = document.getElementById('loadPresetJsonBtn');
    var inp = document.getElementById('presetJsonFile');
    if (!btn || !inp) return;
    btn.addEventListener('click', function(){ inp.click(); });
    inp.addEventListener('change', function(ev){
      var f = ev.target.files && ev.target.files[0];
      if (f) handlePresetFile(f);
      ev.target.value = '';
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPresetJsonLoader);
  } else {
    initPresetJsonLoader();
  }
})();

